const results = await Promise.allSettled([
  tools.exec_command({cmd:"git -C \"$STAMPED_JUDGE_TARGET\" status --short --branch && git -C \"$STAMPED_JUDGE_TARGET\" log --oneline -5 && git -C \"$STAMPED_JUDGE_TARGET\" remote -v && git -C \"$STAMPED_JUDGE_TARGET\" ls-files","yield_time_ms":10000,"max_output_tokens":6000}),
  tools.exec_command({cmd:"cat /Users/johnlee/.local/state/stamped-in-practice/narps-v1/narps-r1-08/judgment-01/worker-end-state.json","yield_time_ms":10000,"max_output_tokens":3000}),
  tools.exec_command({cmd:"find /Users/johnlee/.local/state/stamped-in-practice/narps-v1/narps-r1-08/judgment-01/frozen-inputs/coordinator-guidance -maxdepth 2 -type f -print","yield_time_ms":10000,"max_output_tokens":2000}),
  tools.exec_command({cmd:"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" --help","yield_time_ms":30000,"max_output_tokens":4000}),
  tools.exec_command({cmd:"date -u +%F; pwd; git status --short --branch","yield_time_ms":10000,"max_output_tokens":1000})
]);
for (let i=0;i<results.length;i++) { const x=results[i]; text(`TASK ${i+1}\n${x.status==="fulfilled"?x.value.output:String(x.reason)}`); }

