from array import array
from collections import Counter
import gzip, json, pathlib, struct
root=pathlib.Path('/Users/johnlee/.local/state/stamped-in-practice/narps-v1/narps-r1-08/targets/judgment-01')
def load(path):
    with gzip.open(path,'rb') as f: b=f.read()
    endian='<' if struct.unpack_from('<i',b,0)[0]==348 else '>'
    dims=struct.unpack_from(endian+'8h',b,40)[1:4]
    dtype=struct.unpack_from(endian+'h',b,70)[0]
    offset=int(struct.unpack_from(endian+'f',b,108)[0])
    if dtype==16: a=array('f'); a.frombytes(b[offset:offset+len(b[offset:])//4*4]);
    elif dtype==2: a=array('B'); a.frombytes(b[offset:offset+len(b[offset:])]);
    elif dtype==64: a=array('d'); a.frombytes(b[offset:offset+len(b[offset:])//8*8]);
    else: raise ValueError((path,dims,dtype,offset))
    if a.itemsize>1 and struct.pack('=I',1)!=struct.pack(endian+'I',1): a.byteswap()
    return dims,a
files=sorted((root/'input/data').glob('sub-*_hypo1_cope.nii.gz'))
mask=None; shape=None
for p in files:
    dims,a=load(p)
    if shape is None: shape=dims; mask=bytearray(len(a))
    assert dims==shape and len(a)==len(mask)
    for i,v in enumerate(a):
        if v!=0: mask[i]+=1
hist=Counter(mask)
